DECLARE
V_COUNT INTEGER;
BEGIN
SELECT COUNT(TABLE_NAME) INTO V_COUNT from USER_TABLES where TABLE_NAME = '__EFMigrationsHistory';
IF V_COUNT = 0 THEN
Begin
BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"__EFMigrationsHistory" (
    "MigrationId" NVARCHAR2(150) NOT NULL,
    "ProductVersion" NVARCHAR2(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
)';
END;

End;

END IF;
EXCEPTION
WHEN OTHERS THEN
    IF(SQLCODE != -942)THEN
        RAISE;
    END IF;
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"PONTO_MONITORAMENTO" (
    "ID_PONTO" NUMBER(20,0) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "CODIGO" NVARCHAR2(50) NOT NULL,
    "NOME" NVARCHAR2(120) NOT NULL,
    "DESCRICAO" NVARCHAR2(500),
    "LOGRADOURO" NVARCHAR2(180),
    "BAIRRO" NVARCHAR2(100),
    "CIDADE" NVARCHAR2(100),
    "UF" CHAR(2),
    "LATITUDE" NUMBER(9,6),
    "LONGITUDE" NUMBER(9,6),
    "ATIVO" NUMBER(1) DEFAULT 1 NOT NULL,
    "DATA_CADASTRO" TIMESTAMP WITH TIME ZONE DEFAULT (SYSTIMESTAMP) NOT NULL,
    CONSTRAINT "PK_PONTO_MONITORAMENTO" PRIMARY KEY ("ID_PONTO")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"REQUISICAO_IDEMPOTENCIA" (
    "CHAVE_IDEMPOTENCIA" NVARCHAR2(100) NOT NULL,
    "METODO_HTTP" NVARCHAR2(10) NOT NULL,
    "ROTA" NVARCHAR2(250) NOT NULL,
    "STATUS_HTTP" NUMBER(3),
    "RESPOSTA_JSON" CLOB,
    "DATA_CRIACAO" TIMESTAMP WITH TIME ZONE DEFAULT (SYSTIMESTAMP) NOT NULL,
    "DATA_EXPIRACAO" TIMESTAMP WITH TIME ZONE,
    CONSTRAINT "PK_REQUISICAO_IDEMPOTENCIA" PRIMARY KEY ("CHAVE_IDEMPOTENCIA")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"USUARIO" (
    "ID_USUARIO" NUMBER(20,0) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "NOME" NVARCHAR2(120) NOT NULL,
    "EMAIL" NVARCHAR2(180) NOT NULL,
    "SENHA_HASH" NVARCHAR2(255) NOT NULL,
    "TELEFONE" NVARCHAR2(20),
    "PERFIL" NVARCHAR2(20) DEFAULT N''CIDADAO'' NOT NULL,
    "ATIVO" NUMBER(1) DEFAULT 1 NOT NULL,
    "DATA_CADASTRO" TIMESTAMP WITH TIME ZONE DEFAULT (SYSTIMESTAMP) NOT NULL,
    CONSTRAINT "PK_USUARIO" PRIMARY KEY ("ID_USUARIO")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"LEITURA_ENCHENTE" (
    "ID_LEITURA" NUMBER(20,0) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "ID_PONTO" NUMBER(20,0) NOT NULL,
    "NIVEL_AGUA_CM" NUMBER(10,2) NOT NULL,
    "CHUVA_MM" NUMBER(10,2) DEFAULT 0.0 NOT NULL,
    "ELEVACAO_CM_H" NUMBER(10,2) DEFAULT 0.0 NOT NULL,
    "DATA_HORA_LEITURA" TIMESTAMP WITH TIME ZONE NOT NULL,
    "ORIGEM" NVARCHAR2(20) DEFAULT N''SIMULACAO'' NOT NULL,
    "CHAVE_EVENTO" NVARCHAR2(100),
    "DATA_RECEBIMENTO" TIMESTAMP WITH TIME ZONE DEFAULT (SYSTIMESTAMP) NOT NULL,
    CONSTRAINT "PK_LEITURA_ENCHENTE" PRIMARY KEY ("ID_LEITURA"),
    CONSTRAINT "FK_LEITURA_PONTO" FOREIGN KEY ("ID_PONTO") REFERENCES "PONTO_MONITORAMENTO" ("ID_PONTO")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"ALERTA" (
    "ID_ALERTA" NUMBER(20,0) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "ID_LEITURA" NUMBER(20,0) NOT NULL,
    "CLASSIFICACAO" NVARCHAR2(20) NOT NULL,
    "PROBABILIDADE" NUMBER(5,4),
    "MENSAGEM_EXPLICATIVA" CLOB,
    "TIPO_MENSAGEM" NVARCHAR2(20),
    "MODELO_ML" NVARCHAR2(100),
    "STATUS" NVARCHAR2(20) DEFAULT N''ATIVO'' NOT NULL,
    "DATA_GERACAO" TIMESTAMP WITH TIME ZONE DEFAULT (SYSTIMESTAMP) NOT NULL,
    "DATA_RESOLUCAO" TIMESTAMP WITH TIME ZONE,
    CONSTRAINT "PK_ALERTA" PRIMARY KEY ("ID_ALERTA"),
    CONSTRAINT "FK_ALERTA_LEITURA" FOREIGN KEY ("ID_LEITURA") REFERENCES "LEITURA_ENCHENTE" ("ID_LEITURA")
)';
END;
/

CREATE UNIQUE INDEX "UQ_ALERTA_LEITURA" ON "ALERTA" ("ID_LEITURA")
/

CREATE UNIQUE INDEX "UQ_LEITURA_EVENTO" ON "LEITURA_ENCHENTE" ("CHAVE_EVENTO")
/

CREATE UNIQUE INDEX "UQ_LEITURA_PONTO_DATA" ON "LEITURA_ENCHENTE" ("ID_PONTO", "DATA_HORA_LEITURA")
/

CREATE UNIQUE INDEX "UQ_PONTO_CODIGO" ON "PONTO_MONITORAMENTO" ("CODIGO")
/

CREATE INDEX "IX_IDEMPOTENCIA_EXPIRA" ON "REQUISICAO_IDEMPOTENCIA" ("DATA_EXPIRACAO")
/

CREATE UNIQUE INDEX "UQ_USUARIO_EMAIL" ON "USUARIO" ("EMAIL")
/

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES (N'20261110211026_InitialCreate', N'9.0.0')
/

